module Benchmarks.Paper where

import Clash.Prelude

import MAC
import MAC.Types
  

    
{-# ANN benchmark_MAC_2_InlineFA_Mealy_BitVector_Indexing_IndexCounter
  (Synthesize
      { t_name = "benchmark_MAC_2_InlineFA_Mealy_BitVector_Indexing_IndexCounter"
      , t_inputs = [ PortName "clk"
                    , PortName "rst"
                    , PortName "ena"
                    , PortProduct "" [
                        PortProduct "mulParameters" [
                          PortName "doStartMultiplication",
                          PortProduct "values" [
                            PortName "x",
                            PortName "y"
                          ]
                        ],
                        PortProduct "accumulator" [
                          PortName "doSetAccumulator",
                          PortName "newAccumulatorValue"
                        ]
                      ]
                    ]
      , t_output =  PortProduct "" [
                      PortProduct "product" [PortName "is_valid", PortName "value"]
                    , PortProduct "accumulator" [PortName "is_valid", PortName "accumulator"]
        ]
  }) #-}
      
    
benchmark_MAC_2_InlineFA_Mealy_BitVector_Indexing_IndexCounter :: Clock System -> Reset System -> Enable System -> Signal System (Input 2 2) -> Signal System (Output 2 2)
benchmark_MAC_2_InlineFA_Mealy_BitVector_Indexing_IndexCounter = exposeClockResetEnable $ mkMAC @System @2 @2 (Config {useModuleFullAdder = False, useState = False, useVector = False, useRotation = False, useOneHot = False})
      
  

    
